// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Logout Log out
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Refresh Refresh the token pair
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// SignIn Sign in an existing user
	// (POST /auth/sign-in)
	SignIn(ctx context.Context, request SignInRequestObject) (SignInResponseObject, error)
	// SignUp Register a new user
	// (POST /auth/sign-up)
	SignUp(ctx context.Context, request SignUpRequestObject) (SignUpResponseObject, error)
	// OauthCallback OAuth provider redirect target
	// (GET /auth/{provider}/callback)
	OauthCallback(ctx context.Context, request OauthCallbackRequestObject) (OauthCallbackResponseObject, error)
	// OauthSignIn Start sign-in with an OAuth provider
	// (GET /auth/{provider}/sign-in)
	OauthSignIn(ctx context.Context, request OauthSignInRequestObject) (OauthSignInResponseObject, error)
	// ListCategories List the user's categories
	// (GET /categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// ListProducts List the user's products
	// (GET /products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// BatchProducts Apply product changes
	// (POST /products/batch)
	BatchProducts(ctx context.Context, request BatchProductsRequestObject) (BatchProductsResponseObject, error)
	// PrepareProductImageUploads Prepare image uploads
	// (POST /products/images/batch)
	PrepareProductImageUploads(ctx context.Context, request PrepareProductImageUploadsRequestObject) (PrepareProductImageUploadsResponseObject, error)
	// UpsertPushSubscription Register or update push subscription
	// (PUT /push/subscriptions)
	UpsertPushSubscription(ctx context.Context, request UpsertPushSubscriptionRequestObject) (UpsertPushSubscriptionResponseObject, error)
	// DeletePushSubscription Revoke push subscription
	// (DELETE /push/subscriptions/{subscriptionId})
	DeletePushSubscription(ctx context.Context, request DeletePushSubscriptionRequestObject) (DeletePushSubscriptionResponseObject, error)
	// GetVapidPublicKey Get VAPID public key
	// (GET /push/vapid)
	GetVapidPublicKey(ctx context.Context, request GetVapidPublicKeyRequestObject) (GetVapidPublicKeyResponseObject, error)
	// GetSettings Get settings
	// (GET /settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// PatchSettings Patch settings
	// (PATCH /settings)
	PatchSettings(ctx context.Context, request PatchSettingsRequestObject) (PatchSettingsResponseObject, error)
}

type StrictHandlerFunc func(ctx *echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

